//! The disposable artificial file tree the scenarios browse.
//!
//! Generation is deterministic: the same [`Scale`] and seed produce byte-identical
//! files (timestamps aside), so a failure can be reproduced from the report. The
//! catalogue is documented in docs/developer/ACCEPTANCE.md; keep the two in step.
use super::encode::{self, Member};
use std::{
    fs,
    io::Write,
    path::{Path, PathBuf},
};

/// Fixed seed of every generated byte; recorded in the report.
pub const SEED: u64 = 0x4D45_4143_4345_5054;

/// How large the bulk fixtures are. `Full` is the default; `Smoke` keeps a quick run
/// (and its disk use) small.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Scale {
    Smoke,
    Full,
}

impl Scale {
    fn many_files(self) -> usize {
        match self {
            Self::Smoke => 400,
            Self::Full => 3_000,
        }
    }

    fn huge_text_bytes(self) -> usize {
        match self {
            Self::Smoke => 1 << 20,
            Self::Full => 8 << 20,
        }
    }

    fn huge_binary_bytes(self) -> usize {
        match self {
            Self::Smoke => 2 << 20,
            Self::Full => 24 << 20,
        }
    }
}

/// SplitMix64: small, seedable and good enough for fixture content.
pub struct Random(u64);

impl Random {
    pub fn new(seed: u64) -> Self {
        Self(seed)
    }

    pub fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut value = self.0;
        value = (value ^ (value >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        value = (value ^ (value >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        value ^ (value >> 31)
    }

    pub fn below(&mut self, bound: u64) -> u64 {
        self.next() % bound
    }

    pub fn bytes(&mut self, length: usize) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(length + 8);
        while bytes.len() < length {
            bytes.extend_from_slice(&self.next().to_le_bytes());
        }
        bytes.truncate(length);
        bytes
    }
}

/// One generated catalogue entry, as listed in the report.
pub struct Item {
    pub path: String,
    pub kind: &'static str,
    pub note: &'static str,
}

/// The generated tree and what the scenarios may expect of it.
pub struct Fixture {
    pub root: PathBuf,
    pub scale: Scale,
    pub items: Vec<Item>,
}

